#!/usr/bin/env node
// Builds every generated file from tokens/*.json. Dependency-free.
//   node scripts/build-tokens.mjs           write files
//   node scripts/build-tokens.mjs --check   fail if a generated file is out of date
import { writeFileSync, readFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { load, root, cssName, toCss, modeValue, DEFAULT_BRAND } from './lib/tokens.mjs';

const t = load();
const css = (v, where) => toCss(v, t.index, where);
const decl = (leaf, mode) => `  ${cssName(leaf)}: ${css(modeValue(leaf, mode), leaf.key)};`;
const HEADER = (src) => `/* GENERATED by scripts/build-tokens.mjs from ${src}. Do not edit by hand. */\n`;
const files = new Map();

// ---- src/variables.css ---------------------------------------------------
const prim = t.primitive.filter((l) => l.scope !== 'brand');
const semLight = (mode) => [...t.semantic, ...t.legacy].map((l) => decl(l, mode));
const block = (selectors, mode) =>
  `${selectors.join(',\n')} {\n  color-scheme: ${mode};\n${semLight(mode).join('\n')}\n}\n`;

files.set(
  'src/variables.css',
  `${HEADER('tokens/primitive.json, semantic.json, legacy.json')}
/* Three tiers:
   1. Primitives  raw values (slate, red, space, text...). Never change per theme.
   2. Semantic    meaning (--cu-background, --cu-primary...). Components use only these.
                  Light is the default; [data-cu-theme="dark"] swaps the values.
   3. Brand       the brand scale, fonts and radius live in src/brands/<name>.css.

   The semantic blocks are repeated for nested scopes so a dark section inside a
   light page (or a brand inside a theme) re-resolves its own values. */

/* ---------- 1. Primitives ---------- */
:root {
${prim.map((l) => decl(l)).join('\n')}
}

/* ---------- 2. Semantic: light (default) ---------- */
${block([':root', '[data-cu-brand]', '[data-cu-theme="light"]'], 'light')}
/* ---------- 2. Semantic: dark ---------- */
${block(['[data-cu-theme="dark"]', '[data-cu-theme="dark"] [data-cu-brand]'], 'dark')}
/* ---------- 2. Semantic: light island inside dark ---------- */
${block(['[data-cu-theme="dark"] [data-cu-theme="light"]', '[data-cu-theme="dark"] [data-cu-theme="light"][data-cu-brand]'], 'light')}`
);

// ---- src/brands/*.css ----------------------------------------------------
const derived = t.primitive.filter((l) => l.scope === 'brand');
const brandNames = Object.keys(t.brands).sort((a, b) => (a === DEFAULT_BRAND ? -1 : b === DEFAULT_BRAND ? 1 : a.localeCompare(b)));
for (const name of brandNames) {
  const b = t.brands[name];
  const sel = name === DEFAULT_BRAND ? `:root,\n[data-cu-brand="${name}"]` : `[data-cu-brand="${name}"]`;
  const lines = [...b.leaves.map((l) => `  ${cssName(l)}: ${css(l.value, `${name}:${l.key}`)};`), '', '  /* derived from the radius knob */', ...derived.map((l) => `  ${cssName(l)}: ${l.value};`)];
  files.set(`src/brands/${name}.css`, `${HEADER(`tokens/brands/${b.file}`)}/* ${b.description} */\n${sel} {\n${lines.join('\n')}\n}\n`);
}
files.set(
  'src/brands/index.css',
  `${HEADER('tokens/brands/')}/* The default brand comes first so other brands override it. */\n${brandNames.map((n) => `@import url('./${n}.css');`).join('\n')}\n`
);

// ---- tailwind.css (Tailwind v4 @theme, maps to the semantic tokens) ------
const colorLeaves = [...t.semantic.filter((l) => !['shd', 'bdr'].includes(l.path[0]) && l.key !== 'overlay')];
const twLines = [
  ...colorLeaves.map((l) => `  --color-${l.path.join('-')}: var(${cssName(l)});`),
  ...Object.values(t.brands[DEFAULT_BRAND].leaves).filter((l) => l.path[0] === 'color' && ['brand', 'accent'].includes(l.path[1])).map((l) => `  --color-${l.path.slice(1).join('-')}: var(${cssName(l)});`),
  '  --color-white: var(--cu-white);',
  '  --color-black: var(--cu-black);',
  '  --radius-sm: var(--cu-radius-sm);',
  '  --radius-md: var(--cu-radius-md);',
  '  --radius-lg: var(--cu-radius-lg);',
  '  --font-sans: var(--cu-font-family-default);',
  '  --font-heading: var(--cu-font-family-heading);',
  '  --font-mono: var(--cu-font-family-mono);',
  ...t.semantic.filter((l) => l.path[0] === 'shd').map((l) => `  --shadow-${l.path[1]}: var(${cssName(l)});`),
  ...t.primitive.filter((l) => l.path[0] === 'text').map((l) => `  --text-${l.path[1]}: var(${cssName(l)});`),
];
files.set(
  'tailwind.css',
  `${HEADER('tokens/')}/* Tailwind v4 preset: @import "comet-ui/tailwind.css" after loading comet-ui's CSS.
   Gives bg-background, text-foreground, bg-primary, border-border, rounded-md, font-heading...
   "inline" keeps the var() links, so theme and brand switching still works. */
@theme inline {
${twLines.join('\n')}
}
`
);

// ---- tokens/figma-variables.json (Primitives per brand, Semantic light/dark)
const fig = (p) => p.replace(/\./g, '/');
const figma = {
  $description: 'GENERATED by scripts/build-tokens.mjs. Import with a Figma variables plugin. Semantic values alias the primitive names.',
  collections: [
    {
      name: 'Primitives',
      modes: brandNames,
      variables: [
        ...t.primitive.filter((l) => l.scope !== 'brand').map((l) => ({ name: fig(l.key), values: Object.fromEntries(brandNames.map((n) => [n, l.value])) })),
        ...t.brands[DEFAULT_BRAND].leaves.map((l) => ({ name: fig(l.key), values: Object.fromEntries(brandNames.map((n) => [n, t.brands[n].leaves.find((x) => x.key === l.key)?.value])) })),
      ],
    },
    {
      name: 'Semantic',
      modes: ['Light', 'Dark'],
      variables: t.semantic.map((l) => ({ name: fig(l.key), values: { Light: modeValue(l, 'light'), Dark: modeValue(l, 'dark') }, ...(l.description ? { description: l.description } : {}) })),
    },
  ],
};
files.set('tokens/figma-variables.json', JSON.stringify(figma, null, 2) + '\n');


// ---- src/responsive.css (mobile-first utilities from the breakpoint tokens)
const bps = t.primitive.filter((l) => l.path[0] === 'breakpoint');
const gaps = ['xs', 'sm', 'md', 'lg', 'xl'];
const respBlocks = bps.map((bp) => {
  const n = bp.path[1];
  const rules = [
    `.cu-${n}-hidden { display: none; }`,
    `.cu-${n}-block { display: block; }`,
    `.cu-${n}-flex { display: flex; }`,
    `.cu-${n}-grid { display: grid; }`,
    `.cu-${n}-flex-row { flex-direction: row; }`,
    `.cu-${n}-flex-col { flex-direction: column; }`,
    ...Array.from({ length: 12 }, (_, i) => `.cu-${n}-grid-cols-${i + 1} { grid-template-columns: var(--cu-grid-cols-${i + 1}); }`),
    ...Array.from({ length: 12 }, (_, i) => `.cu-${n}-col-span-${i + 1} { grid-column: span ${i + 1} / span ${i + 1}; }`),
    ...gaps.map((g) => `.cu-${n}-gap-${g} { gap: var(--cu-space-${g}); }`),
  ];
  return `/* ${n}: ${bp.value} and up */\n@media (min-width: ${bp.value}) {\n${rules.map((r) => '  ' + r).join('\n')}\n}\n`;
});
files.set(
  'src/responsive.css',
  `${HEADER('tokens/primitive.json (breakpoint)')}/* Mobile-first. Use cu-md-grid-cols-2 to apply grid-cols-2 from 48rem (768px) and up.
   Combine with a base class: class="cu-grid cu-grid-cols-1 cu-md-grid-cols-2 cu-lg-grid-cols-4" */
${respBlocks.join('\n')}`
);

// ---- write or check ------------------------------------------------------
const check = process.argv.includes('--check');
let stale = 0;
for (const [path, content] of files) {
  const abs = join(root, path);
  if (check) {
    if (!existsSync(abs) || readFileSync(abs, 'utf8') !== content) {
      console.error(`stale  ${path} (run npm run build:tokens)`);
      stale++;
    }
  } else {
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, content);
    console.log(`wrote  ${path}`);
  }
}
process.exit(stale ? 1 : 0);
